-- slc.semantic.wwi_sales (governed profile). Generated by build_metric_views.py.
CREATE OR REPLACE VIEW slc.semantic.wwi_sales
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: 'WideWorldImporters sales at invoice line grain (W-S1, W-M1, B-W1 to B-W4). Stock group analysis: wwi_sales_by_stock_group.'
source: slc.wwi.fact_sale
joins:
- name: inv_cal
  source: slc.wwi.dim_date
  'on': source.invoice_date = inv_cal.date_key
  rely:
    at_most_one_match: true
- name: dlv_cal
  source: slc.wwi.dim_date
  'on': source.delivery_date = dlv_cal.date_key
  rely:
    at_most_one_match: true
- name: cust
  source: slc.wwi.dim_customer
  'on': source.customer_key = cust.customer_key
  rely:
    at_most_one_match: true
- name: bill_cust
  source: slc.wwi.dim_customer
  'on': source.bill_to_customer_key = bill_cust.customer_key
  rely:
    at_most_one_match: true
- name: geo
  source: slc.wwi.dim_city
  'on': source.city_key = geo.city_key
  rely:
    at_most_one_match: true
- name: item
  source: slc.wwi.dim_stock_item
  'on': source.stock_item_key = item.stock_item_key
  rely:
    at_most_one_match: true
  joins:
  - name: item_current
    source: slc.wwi.dim_stock_item
    'on': item.wwi_stock_item_id = item_current.wwi_stock_item_id AND item_current.is_current
    rely:
      at_most_one_match: true
- name: rep
  source: slc.wwi.dim_employee
  'on': source.salesperson_key = rep.employee_key
  rely:
    at_most_one_match: true
fields:
- name: invoice_date
  expr: source.invoice_date
  comment: Shared calendar with a fiscal year starting 1 November, labeled by the year in which it ends.
  display_name: Invoice Date
- name: calendar_year
  expr: inv_cal.calendar_year
  display_name: Calendar Year
- name: calendar_quarter
  expr: inv_cal.calendar_quarter
  display_name: Calendar Quarter
- name: calendar_month
  expr: inv_cal.calendar_month
  display_name: Calendar Month
- name: month_name
  expr: inv_cal.month_name
  display_name: Month Name
- name: month_start_date
  expr: inv_cal.month_start_date
  display_name: Month Start Date
- name: fiscal_year
  expr: inv_cal.fiscal_year
  comment: Fiscal year starting 1 November, labeled by the year in which it ends.
  display_name: Fiscal Year
- name: fiscal_quarter
  expr: inv_cal.fiscal_quarter
  display_name: Fiscal Quarter
- name: fiscal_month
  expr: inv_cal.fiscal_month
  comment: Fiscal month, November = 1.
  display_name: Fiscal Month
- name: day_of_week
  expr: inv_cal.day_of_week
  comment: ISO day of week, Monday = 1.
  display_name: Day Of Week
- name: delivery_date
  expr: source.delivery_date
  comment: Date the invoice line was delivered (role of the Date dimension); blank for undelivered lines.
  display_name: Delivery Date
  synonyms:
  - delivered on
  - ship date
  - delivery day
- name: delivery_year
  expr: dlv_cal.calendar_year
  display_name: Delivery Year
- name: delivery_month_start_date
  expr: dlv_cal.month_start_date
  display_name: Delivery Month Start Date
- name: customer
  expr: cust.customer
  comment: Customer as recorded at the time of sale.
  display_name: Customer
  synonyms:
  - client
  - account
  - store
  - buyer
- name: customer_category
  expr: cust.category
  display_name: Customer Category
- name: buying_group
  expr: cust.buying_group
  display_name: Buying Group
- name: bill_to_customer
  expr: bill_cust.customer
  comment: Customer responsible for payment (role of the Customer dimension).
  display_name: Bill-To Customer
  synonyms:
  - bill to
  - billing customer
  - payer
  - head office
- name: city
  expr: geo.city
  comment: Delivery city as recorded at the time of sale; Sales Territory is an alternate hierarchy over State Province.
  display_name: City
  synonyms:
  - location
  - territory
  - state
- name: state_province
  expr: geo.state_province
  display_name: State Province
- name: country
  expr: geo.country
  display_name: Country
- name: continent
  expr: geo.continent
  display_name: Continent
- name: sales_territory
  expr: geo.sales_territory
  comment: Sales territory of the delivery city at the time of sale.
  display_name: Sales Territory
- name: region
  expr: geo.region
  display_name: Region
- name: subregion
  expr: geo.subregion
  display_name: Subregion
- name: stock_item
  expr: item.stock_item
  comment: Product as recorded at the time of sale (SCD Type 2); current attributes via the durable item id.
  display_name: Stock Item
  synonyms:
  - product
  - item
  - SKU
  - article
- name: wwi_stock_item_id
  expr: item.wwi_stock_item_id
  comment: Durable stock item id (stable across SCD Type 2 versions).
  display_name: WWI Stock Item ID
- name: brand
  expr: item.brand
  display_name: Brand
- name: color
  expr: item.color
  comment: Color as recorded at the time of the fact (as-was).
  display_name: Color
- name: size
  expr: item.size
  display_name: Size
- name: selling_package
  expr: item.selling_package
  display_name: Selling Package
- name: is_chiller_stock
  expr: item.is_chiller_stock
  display_name: Is Chiller Stock
- name: current_color
  expr: item.item_current.color
  comment: Color of the current version of the stock item (as-is).
  display_name: Current Color
- name: salesperson
  expr: rep.employee
  comment: Employee credited with the sale or order (role of the Employee dimension).
  display_name: Salesperson
  synonyms:
  - sales rep
  - seller
  - account manager
  - rep
measures:
- name: revenue
  expr: SUM(total_excluding_tax)
  comment: Sum of invoice line totals excluding tax (fact_sale.total_excluding_tax), dated by invoice date.
  display_name: Revenue (Excl. Tax)
  format:
    type: currency
    currency_code: USD
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - revenue
  - sales
  - net sales
  - sales revenue
  - turnover
  - revenue excluding tax
- name: revenue_including_tax
  expr: SUM(total_including_tax)
  comment: Sum of invoice line totals including tax (fact_sale.total_including_tax).
  display_name: Revenue Including Tax
  format:
    type: currency
    currency_code: USD
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - gross revenue incl tax
  - revenue with tax
  - total including tax
  - invoiced amount
- name: gross_profit
  expr: SUM(profit)
  comment: Sum of invoice line profit (fact_sale.profit).
  display_name: Gross Profit
  format:
    type: currency
    currency_code: USD
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - profit
  - margin dollars
  - gross margin amount
- name: units_sold
  expr: SUM(quantity)
  comment: Sum of invoiced quantity (fact_sale.quantity).
  display_name: Units Sold
  format:
    type: number
    decimal_places:
      type: exact
      places: 0
  synonyms:
  - quantity sold
  - sold units
  - sales quantity
  - units invoiced
- name: invoice_count
  expr: COUNT(DISTINCT wwi_invoice_id)
  comment: Exact count of distinct invoices (fact_sale.wwi_invoice_id). Not additive across any dimension.
  display_name: Invoice Count
  format:
    type: number
    decimal_places:
      type: exact
      places: 0
  synonyms:
  - number of invoices
  - invoices
  - distinct invoices
- name: gross_margin_pct
  expr: CAST(MEASURE(gross_profit) AS DOUBLE) / NULLIF(CAST(MEASURE(revenue) AS DOUBLE), 0)
  comment: Gross Profit divided by Revenue (Excl. Tax), computed from the aggregated numerator and denominator at every grain.
  display_name: Gross Margin %
  format:
    type: percentage
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - margin
  - gross margin
  - GM%
  - margin percent
  - profit margin
$$;
